save(465,dict(paragraphs=["Minati Pradhan is a bilingual poet, short-story writer and independent scholar associated with the Vishwaneedam Center for Asian Blossoming. The centre lists her among its executive co-nurturers, and a Madras Institute of Development Studies programme identifies her as a poet and scholar based in Bangalore. Her author profile names the poetry collection A New Dawn and describes an interest in social questions, education and women’s lives.","‘The Power of Time’, her Kabita Live poem, considers time through a series of contradictions. It destroys and heals, brings acceptance yet can awaken grief, and slips beyond the reach of human invention. The final image of remorse remaining in an empty palm gives these abstract questions a tangible, intimate form."],sources=[source('Vishwaneedam — Nurturers','https://vishwaneedam.org/nurturers/',['Executive co-nurturer; writer and independent scholar, Bangalore.'],access='search_index_full_entry; direct retrieval 406'),source('MIDS — Earth Day 2024 programme','https://www.mids.ac.in/assets/doc/ed_2024.pdf',['Poet and independent scholar, Vishwaneedam, Bangalore; environmental dialogue programme.'],access='search_index_programme_text; direct retrieval throttled'),source('StoryMirror — Minati Pradhan author profile','https://storymirror.com/profile/zffeequc/minati-pradhan',['Bilingual poetry/short stories, independent research, A New Dawn, social/education themes.'])],identity_match='Distinctive Vishwaneedam co-nurturer affiliation and bilingual writing match captured biography; centre and MIDS programme identify same professional context.',poems_read=[dict(id=790,title='The Power of Time',basis='Full English text read: change/absolute reality, destruction/resilience, healing/grief, irreversibility, remorse in palm.')],limitations=['Counsellor certification and four/29 publication totals not independently verified and omitted.','A New Dawn is dated 2018 in retail record and 2019 in anthology contributor note; date omitted.','Institutional source text available in search index; direct centre/PDF access blocked or throttled.','Author profile is self-supplied evidence; no new retail link added after direct retrieval failure.'],research_leads=[dict(url='https://www.abebooks.com/first-edition/New-Dawn-Minati-Pradhan-Studera-Press/30194254642/bd',finding='Indexed book record: Studera Press, 2018, ISBN 9789385883804; direct failed.'),dict(url='https://peacefromharmony.org/docs/Ananta-Giri_Transformative-Harmony.pdf',finding='Indexed contributor note links Bangalore bilingual writer to A New Dawn, dated Studera 2019; discrepancy retained.')],next_action='Independent author/editor review and bibliography-date confirmation.'))
